                if string[1] in 'bB':
                    base = 2
                elif string[1] in 'oO':
                    base = 8
                elif string[1] in 'xX':
                    base = 16
                else:
                    base = 10
            elif string and string[0] in '+-':
                base = 10
                # check after sign
